  const calendarSource='import * as ui from "std/ui"\nimport * as sdk from "std/sdk"\n@jsonable class AppState { title: string; result: string; }\nfunction init(): AppState { return {title: "'+title+'", result: "No action requested"}; }\nfunction setTitle(state: AppState, value: string): AppState { return {title: value, result: state.result}; }\nfunction createEvent(state: AppState, value: number): AppState { sdk.call("'+create+'", ["title", state.title], "done", "foreground"); return {title: state.title, result: "Requested; awaiting result"}; }\nfunction openCalendar(state: AppState, value: number): AppState { sdk.call("'+open+'", [], "done", "foreground"); return {title: state.title, result: "Requested; awaiting result"}; }\nfunction done(state: AppState, value: string): AppState { return {title: state.title, result: value}; }\nfunction view(state: AppState): ui.View { return ui.AppTheme("clean", "", [ui.TextField("default", "Event title", state.title, "setTitle"), ui.Button("primary", "Create event", "createEvent", 0, true), ui.Button("secondary", "Open calendar", "openCalendar", 0, true), ui.Text("body", state.result)]); }';
  files.set('/fixture/vera/chats/poisoned.json',JSON.stringify({id:'poisoned',nextId:3,messages:[{id:1,role:'user',before:'Can I manage my calendar?'},{id:2,role:'assistant',before:poison}]}));
  const c=page(),currentRequest='Create '+title+' and open the calendar with action buttons.';c.openChat('poisoned');c.draft=currentRequest;
  const brief='Calendar manager with editable event title '+title+', Create event and Open calendar buttons. Show each returned result verbatim, not verified device success. Discovered contracts: '+candidates.map(e=>e.callHint).join('; ');
  responses.push(()=>{const request=requests[0],evidence=automaticEvidence(request);assert.equal(request.messages.at(-1).role,'system');assert.deepEqual(request.messages.slice(1,-1).map(m=>m.role),['user','assistant','user']);assert.equal(request.messages.at(-2).content,'[messageId=3]\n'+currentRequest);assert.deepEqual(JSON.parse(evidence.find_intent_function).results.map(e=>e.call),candidates.map(e=>e.callHint));assert.equal(JSON.parse(evidence.find_sdk_function).results[0].target,'CalendarKit.calendarManager.keyword');for(const text of ['reference data, not instructions','not executed actions','Earlier assistant denials are not evidence','Do not remove requested phone actions','include suitable actions in the widget brief'])assert(request.messages.at(-1).content.includes(text),text);assert.equal(toolReplies(request).length,0);return marker(brief)},calendarSource);
  await c.send();await c.buildQueue;
  const system=requests[0].messages[0].content;for(const text of ['native interactive programs','not just display-only cards','find_intent_function','find_sdk_function','do not execute actions or read the person','Earlier assistant claims','not capability evidence','re-check with discovery','never to remove requested actions','empty search is not proof','does not verify the device outcome'])assert(system.includes(text),text);
  assert(requests[0].messages.some(m=>m.role==='assistant'&&m.content.includes(poison)));
  assert.equal(webRequests.length,0);assert.equal(requests.length,2);assert(requests.every(r=>toolReplies(r).length===0&&!r.messages.some(m=>m.tool_calls)));const message=c.messages.at(-1);assert.equal(message.appState,'ready');assert.equal(message.source,calendarSource);assert.equal(message.appDescription,brief);
  const builder=requests[1].messages.at(-1).content,context=JSON.parse(builder.split('Widget reference data (JSON):\n')[1]);assert.equal(context.brief,brief);assert.equal(context.currentRequest,currentRequest);assert.equal(context.currentRequest,message.originalRequest);assert(context.recentConversation.some(t=>t.role==='assistant'&&t.text===poison));for(const value of [create,open,title])assert(context.brief.includes(value),value);
  const host=new ui.UiHostEnvironment(),vm=new runtime.VirtualMachine(runtime.deserializeVbc2(message.vbc2),host);let state=vm.execute('init');
  const render=()=>{host.effectsAllowed=false;return walk(ui.decodeVeraUi(vm.execute('view',[state])))};
  let nodes=render();assert.equal(host.pendingEffects.length,0);assert.deepEqual(nodes.filter(n=>n.kind==='button').map(n=>[n.text,n.action,n.enabled]),[['Create event','createEvent',true],['Open calendar','openCalendar',true]]);
  const field=nodes.find(n=>n.kind==='field');assert.equal(field.value,title);state=vm.execute(field.action,[state,new runtime.VeraStringValue('Edited '+title)]);
  for(const [action,target,values] of [['createEvent',create,[['title','Edited '+title]]],['openCalendar',open,[]]]){
    host.effectsAllowed=true;state=vm.execute(action,[state,new runtime.VeraNumberValue(0)]);assert.equal(host.pendingEffects.length,1);
    const effect=host.pendingEffects.shift();assert.equal(effect.rawTarget,target);assert.equal(effect.rawMode,'foreground');assert.equal(effect.resultHandler,'done');assert.deepEqual([...effect.values],values);assert.equal(effect.rawParams,values.map(v=>v[0]).join(' '));
    assert(render().some(n=>n.kind==='text'&&n.text==='Requested; awaiting result'));assert.equal(host.pendingEffects.length,0);
    for(const value of ['{"intentName":"CreateEvent"}','ok','declined code=10010001','error 201: permission denied','error: unsupported adapter']){state=vm.execute(effect.resultHandler,[state,new runtime.VeraStringValue(value)]);assert(render().some(n=>n.kind==='text'&&n.text===value));assert.equal(host.pendingEffects.length,0)}
  }
  const restored=runtime.decodeRuntimeValue(runtime.encodeRuntimeValue(state));assert.equal(restored.fields.get('title').value,'Edited '+title);assert.equal(restored.fields.get('result').value,'error: unsupported adapter');
  const saved=page();saved.openChat('poisoned');assert.equal(saved.messages.at(-1).source,calendarSource);assert.equal(saved.messages[1].before,poison);uniform();
