for(const mode of ['keyword','embedding'])await check('Calendar adapter wire contracts reach '+mode+' discovery, chat evidence, and generation without filtering',async()=>{
  discoveryFixture();const calendar=vera('VeraCalendarSdk'),deep=vera('DeepSeekEngine'),index=JSON.parse(read('entry/src/main/resources/rawfile/sdk-index.json'));
  const entries=index.filter(e=>e.kit==='CalendarKit'),target=e=>e.kit+'.'+e.module+'.'+e.name;
  assert.equal(entries.length,20);assert.deepEqual(entries.map(target).sort(),[...calendar.calendarSdkTargets].sort());
  const unsupported={kit:'CalendarKit',module:'Calendar',name:'futureMethod',params:'native: Calendar',returnType:'Promise<void>',summary:'Future calendar summary',description:'Future calendar description'};
  const other={kit:'OtherKit',module:'Calendar',name:'addEvent',params:'event: NativeEvent',returnType:'Promise<number>',summary:'',description:'Unchanged non-calendar description'};
  let selected=[];const seen=[];
  patch(vera('VeraSdkIndex'),'findSdkFunctionFromCache',(need,limit)=>{if(limit!==SDK_ALSO_DEPTH)seen.push({via:'keyword',need,limit});return mode==='keyword'?selected:[unsupported]});
  patch(vera('VeraSdkEmbeddingCache'),'findSdkFunctionByEmbedding',async(need,limit)=>{if(limit!==SDK_ALSO_DEPTH)seen.push({via:'embedding',need,limit});return mode==='embedding'?selected:null});
  const expected=e=>{const contract=calendar.calendarSdkContract(target(e));return contract?{target:target(e),params:contract.params,returnType:contract.returnType,description:contract.description,implemented:true}:{target:target(e),params:e.params,returnType:e.returnType,description:e.summary||e.description}};
  for(let offset=0;offset<entries.length;offset+=10){
    selected=[other,...entries.slice(offset,offset+10),unsupported];const snapshot=JSON.stringify(selected);
    const result=JSON.parse(await deep.discoveryToolResult('find_sdk_function','calendar wire contracts'));
    assert.deepEqual(sdkResults(result.results),selected.map(expected));assert.equal(JSON.stringify(selected),snapshot);
    assert.deepEqual(result.results.map(e=>e.target),selected.map(target));
    for(const item of result.results.filter(e=>e.implemented))assert.equal(item.returnType,'string');
  }
  const batch=expected(entries.find(e=>e.name==='addEvents'));assert.match(batch.params,/events: JSON Event wire array/);assert.match(batch.description,/native void becomes ok, not IDs/);
  const filter=expected(entries.find(e=>e.name==='filterById'));assert.equal(filter.params,'ids: comma-separated positive int32 decimal (1..2147483647) IDs');assert.match(filter.description,/immutable JSON descriptor/);
  const manager=expected(entries.find(e=>e.name==='getCalendarManager'));assert.equal(manager.params,'');assert.match(manager.description,/vera-calendar-manager/);
  const calls=[call('find_sdk_function','calendar-wire','calendar wire contracts')];responses.push({toolCalls:calls},'Contracts checked.',{toolCalls:calls},source);
  await reply();const built=await chat.buildMiniApp('SKILL','Calendar actions',()=>{});assert.equal(built.error,'');assert.equal(requests.length,4);
  const evidence=automaticEvidence(requests[0]).find_sdk_function,chatResults=toolReplies(requests[1]),buildResults=toolReplies(requests[3]);
  assert.deepEqual(sdkResults(JSON.parse(evidence).results),selected.map(expected));assert.equal(chatResults[0].content,evidence);assert.deepEqual(buildResults,chatResults);
  assert.equal(seen.length,10);assert(seen.every(s=>s.limit===16));assert.deepEqual(seen.map(s=>s.via),Array.from({length:5},()=>['keyword','embedding']).flat());assert.equal(webRequests.length,0);uniform();
});
